import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const repoRoot = process.env.DEVNS_ROOT;
const mode = process.env.DEVNS_HOST_ADAPTER_MODE || 'claim';
const outDir = path.join(process.cwd(), '.devns/artifacts/t3');
fs.mkdirSync(outDir, { recursive: true });

function spawn(command, args, options = {}) {
  const result = spawnSync(command, args, {
    cwd: process.cwd(),
    encoding: 'utf8',
    input: options.input,
    timeout: 20000,
    env: { ...process.env, ...(options.env || {}) }
  });
  return {
    command: [command, ...args].join(' '),
    status: result.status,
    signal: result.signal,
    stdout: result.stdout || '',
    stderr: result.stderr || '',
    error: result.error?.message
  };
}

function approvedRfc() {
  return {
    status: 'approved',
    summary: 'Host adapter execution seed RFC.',
    background: 'The seed verifies that installed host adapter files are executable as a real stop hook path.',
    featureDescription: 'Claim a ready feature through the Codex Stop Hook command adapter.',
    expectedOutcome: 'The adapter delegates to devns:stop and records a claim_next_block decision.',
    goals: ['Verify executable Codex Stop Hook adapter behavior'],
    nonGoals: ['Do not call an external LLM provider'],
    requirements: [{ id: 'REQ-001', type: 'explicit', statement: 'Codex Stop Hook adapter must execute the project stop command and claim approved ready work.', priority: 'must' }],
    acceptanceCriteria: [{ id: 'AC-001', requirementIds: ['REQ-001'], statement: 'Ready feature is claimed by the adapter-backed stop hook.', verification: 'Run Codex Stop Hook adapter in seed repo.', verificationType: 'command' }],
    validationPlan: { dynamic: ['node scripts/run-codex-host-adapter.mjs'], static: [] },
    testCases: [{ id: 'TC-001', acceptanceCriteriaIds: ['AC-001'], type: 'integration', scenario: 'Run installed Codex Stop Hook adapter.', expected: 'Feature becomes in_progress and stop log records adapter exec plus core claim_next_block.' }],
    unknowns: [],
    risks: [],
    humanDecision: { status: 'approved' }
  };
}

function readyFeature() {
  return {
    id: 'HOST-EXEC-001',
    title: 'Host adapter execution seed',
    description: 'Ready feature used to verify Codex adapter execution.',
    status: 'ready',
    priority: 'P0',
    milestone: 'T3',
    risk: 'medium',
    acceptanceCriteria: ['Ready feature is claimed by Codex Stop Hook adapter.'],
    verification: ['node scripts/run-codex-host-adapter.mjs'],
    evidence: [],
    changedFiles: ['src/host-adapter.ts'],
    reviewDecision: 'pending',
    rfc: approvedRfc()
  };
}

if (!repoRoot) {
  throw new Error('DEVNS_ROOT is required.');
}

const tsx = path.join(repoRoot, 'node_modules', '.bin', process.platform === 'win32' ? 'tsx.cmd' : 'tsx');
const initCli = path.join(repoRoot, 'packages/core/src/cli/init.ts');
const stopCli = path.join(repoRoot, 'packages/core/src/cli/stop-hook.ts');
const scripts = mode === 'claim' ? { 'devns:stop': `${tsx} ${stopCli}` } : {};

fs.writeFileSync(path.join(process.cwd(), 'package.json'), `${JSON.stringify({ type: 'module', scripts }, null, 2)}\n`);
const init = spawn(tsx, [initCli, '--force', '--project-name', 'Host Adapter Execution Seed', '--project-description', 'Evaluate Codex Stop Hook adapter execution.', '--host', 'codex']);

let hook = null;
let parsedHook = null;
let inventory = null;
let stopLog = [];
if (init.status === 0) {
  fs.writeFileSync(path.join(process.cwd(), '.devns/features.json'), `${JSON.stringify({ project: { name: 'Host Adapter Execution Seed', description: 'Evaluate Codex Stop Hook adapter execution.' }, features: [readyFeature()] }, null, 2)}\n`);
  const hookScript = path.join(process.cwd(), 'plugins/codex/devns/scripts/devns-stop-hook.sh');
  hook = spawn('bash', [hookScript], { input: JSON.stringify({ cwd: process.cwd() }) });
  try {
    parsedHook = hook.stdout.trim() ? JSON.parse(hook.stdout.trim()) : null;
  } catch {}
  try {
    inventory = JSON.parse(fs.readFileSync(path.join(process.cwd(), '.devns/features.json'), 'utf8'));
  } catch {}
  try {
    stopLog = fs.readFileSync(path.join(process.cwd(), '.devns/history/stop-hook.jsonl'), 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line));
  } catch {}
}

const feature = inventory?.features?.find((item) => item.id === 'HOST-EXEC-001');
const adapterStart = stopLog.some((entry) => entry.source === 'adapter' && entry.phase === 'start');
const adapterExec = stopLog.some((entry) => entry.source === 'adapter' && entry.phase === 'exec');
const adapterMissingCommand = stopLog.some((entry) => entry.source === 'adapter' && entry.phase === 'missing_command');
const coreClaim = stopLog.some((entry) => entry.source === 'core' && entry.mode === 'claim_next_block' && entry.selectedFeatureId === 'HOST-EXEC-001');
const claimed = parsedHook?.decision === 'block' && /Claimed next feature HOST-EXEC-001/.test(parsedHook.reason || '') && feature?.status === 'in_progress';
const stopCommandFound = Boolean(scripts['devns:stop'] && adapterExec && !adapterMissingCommand);
const artifact = {
  projectType: 'host-adapter',
  riskArea: 'host_adapter_execution',
  mode,
  initStatus: init.status,
  hookStatus: hook?.status,
  hookDecision: parsedHook?.decision,
  hookReason: parsedHook?.reason,
  featureStatus: feature?.status || 'missing',
  claimed,
  stopCommandFound,
  adapterStart,
  adapterExec,
  adapterMissingCommand,
  coreClaim,
  logModes: stopLog.map((entry) => entry.mode || entry.phase).filter(Boolean),
  stdoutBytes: hook?.stdout?.length || 0,
  stderrBytes: hook?.stderr?.length || 0,
  errors: [init.error, hook?.error].filter(Boolean)
};
fs.writeFileSync(path.join(outDir, 'codex-host-adapter-execution.json'), `${JSON.stringify(artifact, null, 2)}\n`);

if (init.status !== 0 || hook?.status !== 0) {
  process.exit(1);
}
